// 1. Inline Functions (C++ / C99)
inline int fast_add(int a, int b) {
    return a + b;
}
void caller() {
    int result = fast_add(5, 7);
    // Compiler attempts replacement at call site
}
// Note: 'inline' is a hint, not a command.

// 2. Macros for Trivial Operations (C/C++)
#define SQUARE(x) ((x) * (x))
int val = SQUARE(5);
// Caution: Macro evaluation order issues (side effects)
// e.g., SQUARE(++i) evaluates to (++i) * (++i)

// 3. Loop Unrolling (Reducing Iteration Overhead)
// Original loop: 4 calls to check loop condition
for (int i = 0; i < N; i += 4) {
    a[i] = b[i] + c[i];
    a[i+1] = b[i+1] + c[i+1];
    a[i+2] = b[i+2] + c[i+2];
    a[i+3] = b[i+3] + c[i+3];
}
// Note: Increases instruction cache pressure.

// 4. Function Template Specialization (C++)
// Allows inlining even complex operations known at compile time
template <typename T>
T add_default(T a, T b) { return a + b; }
int x = add_default<int>(1, 2);
// Monomorphization eliminates run-time dispatch overhead.

// 5. Using __attribute__((always_inline)) (GCC/Clang)
__attribute__((always_inline))
int guaranteed_add(int a, int b) {
    return a + b;
}
// Forces inlining if compiler constraints allow.

// 6. Replacing Virtual Calls (C++)
// Avoids V-Table lookup and indirect branch overhead
// Change:
// virtual void foo() { ... }
// To:
// void foo() final { ... } // Or remove virtual entirely

// 7. Replacing Recursion with Iteration
// Recursive: high stack frame overhead
int fib_rec(int n) {
    if (n <= 1) return n;
    return fib_rec(n-1) + fib_rec(n-2);
}
// Iterative (reduced overhead):
int fib_iter(int n) {
    int a=0, b=1, temp;
    for (int i=2; i<=n; ++i) {
        temp = a + b; a = b; b = temp;
    }
    return b;
}
